# BOLDigger3 top-hit selection: identity with BOLDigger3 3.0.2 on hit tables
# generated by validation/boldigger3_reference.py (synthetic, seed 2).

function _bd3_read_tsv(path)
    lines = readlines(path)
    header = split(lines[1], '\t')
    cols = [Union{Missing,String}[] for _ in header]
    for l in lines[2:end]
        for (j, x) in enumerate(split(l, '\t'; keepempty = true))
            push!(cols[j], isempty(x) ? missing : x == "\"\"" ? "" : String(x))
        end
    end
    DataFrame([Symbol(h) => c for (h, c) in zip(header, cols)])
end

@testset "BOLDigger3 top hits" begin
    @testset "Names cleaned as BOLDigger3" begin
        @test boldigger3_name("Baetis rhodani") == "Baetis rhodani"
        @test boldigger3_name("Simulium ornatum-group") == "Simulium ornatum-group"
        @test boldigger3_name("no-match") == "no-match"
        for bad in ("Baetis sp.", "Baetis sp. 1", "Gammarus cf. pulex", "Diptera sp. BIOUG1234-A01",
                    "Simulium (Nevermannia)", "None", "", missing, nothing)
            @test boldigger3_name(bad) === missing
        end
    end

    @testset "Identical to BOLDigger3 3.0.2 (synthetic oracle)" begin
        dir = joinpath(@__DIR__, "data", "boldigger3")
        hits = _bd3_read_tsv(joinpath(dir, "input_hits.tsv"))
        hits.pct_identity = parse.(Float64, hits.pct_identity)
        exp = _bd3_read_tsv(joinpath(dir, "expected.tsv"))
        got = boldigger3_select(hits)
        @test got.id == exp.id
        num(x) = x === missing ? missing : parse(Float64, x)
        ties = parse.(Int, exp.top_ties)
        @test got.tied_groups == ties
        untied = ties .<= 1
        @test count(untied) > 400
        for c in (RANKS..., :status, :selected_level, :BIN, :flags)
            @test isequal(got[untied, c], exp[untied, c])
        end
        @test isequal(got.pct_identity[untied], num.(exp.pct_identity[untied]))
        @test got.records == parse.(Int, exp.records)
        @test isequal(got.records_ratio, num.(exp.records_ratio))     # also with ties
        @test isequal(got.selected_level, exp.selected_level)
        # tied winners: BOLDigger3 follows numpy's non-stable sort; the first
        # group in hit order is its choice in most cases
        @test count(isequal.(got.species[.!untied], exp.species[.!untied])) >= 0.9 * count(.!untied)
    end

    @testset "Rule details" begin
        h(id, sp, pct; genus = "Baetis", status = "public", bin = "BOLD:A1", method = missing) =
            (id = id, phylum = "Arthropoda", class = "Insecta", order = "Ephemeroptera",
             family = "Baetidae", genus = genus, species = sp, pct_identity = pct, status = status,
             bin_uri = bin, identification_method = method)
        hits = DataFrame([
            h("a", "Baetis rhodani", 99.0; method = "BOLD ID Engine"),
            h("a", "Baetis rhodani", 98.0; bin = "BOLD:A2", method = "BIN Taxonomy Match"),
            h("a", "Baetis vardarensis", 97.5),
            h("a", "Baetis rhodani", 90.0; bin = "BOLD:A3"),          # below 97: still in top_hits
            h("b", "Baetis sp. 1", 96.0; status = "private"),         # invalid species, genus level
            h("c", "no-match", 0.0; genus = "no-match", status = "private", bin = missing),
            h("d", "Baetis rhodani", 40.0; genus = missing),          # nothing at 50 %: unidentified
        ])
        r = boldigger3_select(hits)
        @test r.id == ["a", "b", "c", "d"]
        @test r.species[1] == "Baetis rhodani" && r.selected_level[1] == "species"
        @test r.records[1] == 2 && r.records_ratio[1] == 2 / 3
        @test r.BIN[1] == "BOLD:A1|BOLD:A2|BOLD:A3"
        @test r.flags[1] == "1|2|||5"  # records without a method are ignored (dropna)
        @test r.genus[2] == "Baetis" && r.species[2] === missing && r.selected_level[2] == "genus"
        @test r.BIN[2] == "" && r.flags[2] == "||3|4|"
        @test r.species[3] == "no-match" && r.records[3] == 0 && r.records_ratio[3] === missing
        @test r.selected_level[3] === missing && r.flags[3] == "||||"
        @test all(x -> x === missing, (r[4, c] for c in RANKS)) && r.records_ratio[4] == 0.0
        @test_throws ArgumentError boldigger3_select(select(hits, Not(:bin_uri)))
        @test_throws ArgumentError boldigger3_select(hits; ties = :last)
    end

    @testset "Input from bold_identify hits" begin
        hits = DataFrame(sequence = ["ACGT", "ACGT", "ACGT", "TTTT"],
                         process_id = ["P1", "P2", "P3", missing], bin_uri = ["B1", "B2", missing, missing],
                         record_status = ["public", "private", "public", missing],
                         similarity = [97.0, 99.0, 97.0, missing],
                         phylum = ["Arthropoda", "Arthropoda", "Arthropoda", missing],
                         class = ["Insecta", "Insecta", "Insecta", missing],
                         order = ["Diptera", "Diptera", "Diptera", missing],
                         family = ["Simuliidae", "Simuliidae", "Simuliidae", missing],
                         genus = ["Simulium", "Simulium", "Simulium", missing],
                         species = ["Simulium ornatum", "Simulium ornatum", "Simulium ornatum", missing])
        meta = DataFrame(processid = ["P1", "P1", "P3"], identification_method = ["Morphology", "Morphology", missing])
        b = boldigger3_hits(hits; ids = Dict("ACGT" => "ASV1", "TTTT" => "ASV2"), metadata = meta)
        @test b.id == ["ASV1", "ASV1", "ASV1", "ASV1", "ASV2"]
        @test b.process_id[1:4] == ["P2", "P1", "P1", "P3"]     # by similarity, then BOLD order
        @test b.status[1:4] == ["private", "public", "public", "public"]  # P1 twice (two markers)
        @test b.species[5] == "no-match" && b.pct_identity[5] == 0.0 && b.status[5] == "private"
        s = boldigger3_select(b)
        @test s.records[1] == 4 && s.BIN[1] == "B2|B1" && s.status[1] == "private"
        @test s.species[2] == "no-match"
        plain = boldigger3_hits(hits)
        @test plain.id[1] == "ACGT" && plain.status[1:3] == ["private", "public", "public"]
        @test plain.status[4] === missing
    end
end
